# Full preflight: simulate every sequential replacement in memory before writing any file.
originals = {}
planned = {}
for path, old, new, label in OPERATIONS:
    file = ROOT / path
    if path not in planned:
        if not file.is_file():
            raise SystemExit(f"{label}: missing file {path}")
        text = file.read_text(encoding="utf-8")
        originals[path] = text
        planned[path] = text
    text = planned[path]
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly one match in {path}, found {count}")
    planned[path] = text.replace(old, new, 1)

for path in NEW_FILES:
    if (ROOT / path).exists():
        raise SystemExit(f"new file already exists: {path}")

# Write only after every anchor and new-file precondition has passed.
written_existing = []
written_new = []
try:
    for path, text in planned.items():
        (ROOT / path).write_text(text, encoding="utf-8")
        written_existing.append(path)
    for path, content in NEW_FILES.items():
        file = ROOT / path
        file.parent.mkdir(parents=True, exist_ok=True)
        file.write_text(content, encoding="utf-8")
        written_new.append(path)
except Exception:
    for path in reversed(written_new):
        try:
            (ROOT / path).unlink(missing_ok=True)
        except Exception:
            pass
    for path in reversed(written_existing):
        try:
            (ROOT / path).write_text(originals[path], encoding="utf-8")
        except Exception:
            pass
    raise

print(f"Feed region hardening patch applied to {len(planned)} existing files and {len(NEW_FILES)} new tests.")
print("Run ./gradlew test before committing.")
